class Solution {
    public int[] nextGreaterElement(int[] nums1,int[] nums2){
        Map<Integer,Integer> next=new HashMap<>();
        Deque<Integer> stack=new ArrayDeque<>();
        for(int value:nums2){
            while(!stack.isEmpty()&&stack.peek()<value)next.put(stack.pop(),value);
            stack.push(value);
        }
        int[] answer=new int[nums1.length];
        for(int i=0;i<nums1.length;i++)answer[i]=next.getOrDefault(nums1[i],-1);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun nextGreaterElement(nums1:IntArray,nums2:IntArray):IntArray{
        val next=hashMapOf<Int,Int>();
        val stack=ArrayDeque<Int>();
        for(value in nums2){
            while(stack.isNotEmpty()&&stack.last()<value)next[stack.removeLast()]=value;
            stack.addLast(value)
        };
        return IntArray(nums1.size){
            next[nums1[it]]?:-1
        }
    }
}

